  'integrations.kicker': 'Integrasi',
  'integrations.lede': 'Hubungkan sistem eksternal, bawa alat MCP ke dalam loop agent Anda, dan gunakan Pixflow Design dari IDE, skrip, dan otomatisasi lainnya.',
