  "ui.finalOnboarding.125903ce05": "Pembersihan konteks browser diminta. Chat yang tersimpan tetap dipertahankan.",
  "ui.mediaStarter.image1.title": "Potret editorial",
  "ui.mediaStarter.image1.tag": "Potret",
  "ui.mediaStarter.image1.prompt": "Potret editorial jarak dekat seorang direktur kreatif muda berusia akhir 20-an, cahaya alami lembut melalui jendela studio yang tinggi, palet netral hangat (krem, taupe, hitam lembut), bidikan 85mm f/1.8 dengan kedalaman bidang dangkal, tatapan tajam langsung ke kamera, grain film halus, tampilan tanpa riasan.",
  "ui.mediaStarter.image2.title": "Gambar utama produk",
  "ui.mediaStarter.image2.tag": "E-commerce",
  "ui.mediaStarter.image2.prompt": "Foto utama produk premium berupa satu cangkir kopi keramik matte di atas latar kertas krem hangat. Cahaya tepi keras dari kiri atas, bayangan memanjang lembut ke kanan bawah, uap tipis naik dari cangkir. Potongan persegi, komposisi terpusat, ruang judul di atas, tanpa properti atau tangan.",
  "ui.mediaStarter.image3.title": "Ilustrasi datar",
  "ui.mediaStarter.image3.tag": "Ilustrasi",
  "ui.mediaStarter.image3.prompt": "Ilustrasi vektor datar sudut baca nyaman di dekat jendela berhujan—bentuk geometris, palet 5 warna terkendali (krem, terakota, teal tua, sienna bakar, hitam lembut), aksen garis tipis 1.5px, tanpa gradien atau tekstur, bayangan lembut hanya pada kursi berlengan di depan.",
  "ui.mediaStarter.video1.title": "Pengungkapan produk",
  "ui.mediaStarter.video1.tag": "Sinematik",
  "ui.mediaStarter.video1.prompt": "Pengungkapan produk 5 detik: botol perawatan kulit minimalis premium di permukaan batu krem bersih, cahaya samping lembut dari kiri kamera, kamera perlahan mendekat, perpindahan fokus tipis dari tutup ke label, gerak terkendali, tanpa teks overlay atau orang.",
  "ui.mediaStarter.video2.title": "Close-up lentera",
  "ui.mediaStarter.video2.tag": "Suasana",
  "ui.mediaStarter.video2.prompt": "Close-up sinematik 6 detik seorang wanita muda memegang lentera kertas bercahaya di hutan pinus berkabut saat golden hour. Fokus dangkal pada mata, dolly-in lembut, partikel melayang dalam berkas cahaya hangat, tanpa dialog, hanya suara hutan.",
  "ui.mediaStarter.video3.title": "Drift jalan neon",
  "ui.mediaStarter.video3.tag": "Aksi",
  "ui.mediaStarter.video3.prompt": "Bidikan pelacakan balap jalanan 5 detik pada malam hari di gang Hong Kong cyberpunk bercahaya neon. Kamera sudut rendah mengikuti mobil sport hitam matte melayang di tikungan tajam, motion blur pada roda, flare lensa dari papan neon mendekat, aspal basah memantulkan cahaya, tanpa teks layar.",
  "ui.mediaStarter.hyperframes1.title": "Pengungkapan kaca pembesar",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Buat komposisi 5 detik dengan satu baris teks tebal pada kanvas bersih. Animasikan kaca pembesar bundar dari kiri ke kanan, membengkokkan huruf di bawahnya dengan refraksi kaca halus. Gunakan HyperFrames html-in-canvas: tangkap DOM teks dan jalankan shader lensa di atasnya melalui pass bergaya vfx-liquid-glass. Teks memakai CSS murni; kaca berupa lapisan WebGL.",
  "ui.mediaStarter.hyperframes2.title": "Adegan terminal CRT",
  "ui.mediaStarter.hyperframes2.tag": "VFX vintage",
  "ui.mediaStarter.hyperframes2.prompt": "Buat komposisi layar CRT: kanvas gelap, teks terminal monospace mengetik `npx hyperframes init my-video`, lalu memanggil `claude` dengan prompt 'Add a CRT effect using HTML-in-canvas'. Terapkan shader kelengkungan cembung halus, scanline, sedikit aberasi kromatik, dan cahaya fosfor lembut di atas DOM langsung melalui html-in-canvas. Teks terminal tetap CSS asli agar tajam sebelum pass shader.",
  "ui.mediaStarter.hyperframes3.title": "Pecahan glitch",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Buat komposisi 6 detik yang menampilkan judul utama dan subjudul satu baris pada kanvas gelap, lalu pecah menjadi glitch digital kuat—pemisahan kanal RGB, pita perpindahan horizontal, tersendatnya bingkai sesaat, dan reset bersih di akhir. Tangkap DOM langsung melalui html-in-canvas dan jalankan pass glitch di atasnya agar tipografi tetap CSS asli di bawah shader.",
  "ui.mediaStarter.audio1.title": "Sulih suara merek",
  "ui.mediaStarter.audio1.tag": "Ucapan",
  "ui.mediaStarter.audio1.prompt": "Narasi hangat 30 detik untuk video peluncuran produk—percaya diri tetapi percakapan, tempo sedang, jeda sesaat setelah nama merek. Naskah: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' Bahasa Inggris, aksen Amerika Utara netral.",
  "ui.mediaStarter.audio2.title": "Narasi pengenalan",
  "ui.mediaStarter.audio2.tag": "Ucapan",
  "ui.mediaStarter.audio2.prompt": "Narasi pengenalan ramah 20 detik untuk layar peluncuran pertama aplikasi seluler. Nada menenangkan dan tersenyum, cukup lambat agar terasa penuh perhatian tanpa terdengar membaca naskah. Naskah: 'Selamat datang di Loop. Mari siapkan ruang Anda—tiga pertanyaan singkat, lalu Anda siap. Semua ini bisa diubah nanti.'",
  "ui.mediaStarter.audio3.title": "Pembacaan petikan cerita",
  "ui.mediaStarter.audio3.tag": "Ucapan",
  "ui.mediaStarter.audio3.prompt": "Pembacaan sinematik 45 detik untuk bagian pembuka. Suara rendah dan terukur, napas di antara kalimat, sedikit intim seperti dekat mikrofon. Naskah: 'Kota tidur dalam kepingan. Papan neon berkedip di atas konter ramen. Di seberang jalan, sebuah jendela bercahaya—satu-satunya yang masih menyala di sisi tengah malam ini.'",
